# Now, let's remove the identified old songs from their respective playlists.
# We'll call the Spotify API to remove songs from each playlist using the playlist_old_song_ids mapping.

for playlist_id, song_ids in playlist_old_song_ids.items():
    if song_ids:
        apis.spotify.remove_songs_from_playlist(
            playlist_id=playlist_id,
            song_ids=song_ids,
            access_token=spotify_access_token
        )

# Next, we need to check if the "Archived Songs" playlist exists, and create it if it doesn't.
playlists_lower = {pl["name"].strip().lower(): pl for pl in playlists}
archived_playlist = playlists_lower.get("archived songs")
if archived_playlist:
    archived_playlist_id = archived_playlist["id"]
else:
    created = apis.spotify.create_playlist(
        name="Archived Songs",
        description="Songs archived from old playlists.",
        access_token=spotify_access_token
    )
    archived_playlist_id = created["id"]

print("archived_playlist_id:", archived_playlist_id)

