# The "show_playlist" API returns a "songs" field with song IDs, titles, and artist_ids.
# Let's refresh the song lists for all playlists by calling this API for each playlist.
# We'll build a new mapping: playlist_id_to_song_ids_refreshed.

playlist_id_to_song_ids_refreshed = {}
for playlist_id in playlist_id_to_song_ids.keys():
    resp = apis.spotify.show_playlist(playlist_id=playlist_id, access_token=spotify_access_token)
    if isinstance(resp, dict) and "songs" in resp:
        playlist_id_to_song_ids_refreshed[playlist_id] = [song["id"] for song in resp["songs"]]
    else:
        playlist_id_to_song_ids_refreshed[playlist_id] = []

print(playlist_id_to_song_ids_refreshed)

